.sb-search {
float:right;
  top: 0;
  right: 0;
  -webkit-transition: width 0.3s;
  -moz-transition: width 0.3s;
  transition: width 0.3s;
  overflow: hidden;
  -webkit-backface-visibility: hidden;}
.sb-search-input {
	position: absolute;
	top: 0;
	right: 0;
	border: none;
	outline: none;
	background: #fff;
	width: 100%;
	height: 60px;
	margin: 0;
	z-index: 10;
	padding: 20px 65px 20px 20px;
	font-family: inherit;
	font-size: 20px;
	color: #2c3e50;
}

input[type="search"].sb-search-input {
	-webkit-appearance: none;
    padding: 1px 5px;
    -webkit-border-radius: 0;
    height: 36px;
    font-size: 13px;
    font-weight: 400;
    margin-top: 0px;
    margin-bottom: 0;
    border-left: none;
    border-top: none;

}
.sb-search-input::-webkit-input-placeholder {
	color: #999;
}

.sb-search-input:-moz-placeholder {
	color: #999;
}

.sb-search-input::-moz-placeholder {
	color: #999;
}

.sb-search-input:-ms-input-placeholder {
	color: #999;
}
.sb-icon-search, .sb-search-submit  {
	width: 15px!important;
	display: block;
	position: absolute;
	right: 0;
	top: 0;
	padding: 0;
	margin: 0;
	line-height: 49px;
	text-align: center;
	cursor: pointer;
}
.sb-search-submit {
	-ms-filter: "progid:DXImageTransform.Microsoft.Alpha(Opacity=0)"; /* IE 8 */
    filter: alpha(opacity=0); /* IE 5-7 */
    opacity: 1;
	border: none;
	outline: none;
	z-index: -1;
}

.sb-icon-search {
	z-index: 99;
	font-size: 15px;
	font-family: 'fontAwesome';
	speak: none;
	font-style: normal;
	font-weight: normal;
	font-variant: normal;
	text-transform: none;
	-webkit-font-smoothing: antialiased;
}
.iconopen:before {
    content: "\f00d";
}
.sb-icon-search:before {
	content: "\f002";
}


.sb-search.sb-search-open .sb-icon-search{
	background: #000;
	z-index: 99999;
}


.no-js .sb-search .sb-icon-search {
	background: #000;
	color: #696969;
	z-index: 11;
}

.sb-search.sb-search-open .sb-search-submit,
.no-js .sb-search .sb-search-submit {
	z-index: 90;
}

input[type="search"]:focus{border:none;-webkit-box-shadow: none;
-moz-box-shadow: none;
box-shadow: none;}



