        width: 100%;
        border-spacing: 20px;
        padding: 25px 0;
        max-width: 1150px;
        margin: 0 auto;
    }
    .featured-box-item { 
        height: 112px;
        width: 112px;
        border-radius: 50%;
        clear: both;
        display: block;
        background-size: cover;
        background-repeat: no-repeat;
        background-position: center center;
        margin:0 auto;
        -webkit-transition: 600ms;
        -moz-transition: 600ms;
        -ms-transition: 600ms;
        -o-transition: 600ms;
        transition: 600ms;
    }


    .featured-box-overlay {
        text-align: center;
        max-width: 112px;
        margin: 10px auto 0;
    }

    .featured-box-overlay h4 {
        color: #222;
        line-height: 1.5em;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 1px;
        display: inline-block;
        font-weight: 500;
        margin-bottom:0;
        position: relative;
        z-index:0;
    }
    .featured-box-area .widget {
        display: table-cell;
        position: relative;
        vertical-align:top;
    }
    .featured-boxes-wrap {
        margin-top: 50px;
    }
    .featured-boxes-wrap{
        margin-top: 0px;
	    background: #ECECEC;
    }
    .featured-boxes-wrap h2.title, .featured-boxes-wrap h3.title {
        display: none;
    }

	.featured-box-link .featured-box-overlay h4:after {
        position: absolute;
        bottom: 0;
		top:0;
        left: -6px;
		padding: 2px 6px;
        display: block;
        width: 100%;
        height: 100%;
        background: $(backcolor);
        content: "";
        transition: transform .4s ease;
        -webkit-transform: scaleX(0);
        -ms-transform: scaleX(0);
        transform: scaleX(0);
        z-index:-1;
    }
.featured-box-area .widget:hover .featured-box-overlay h4 {
    color: #fff;
}
    .featured-box-area .widget:hover .featured-box-overlay h4:after {
        -webkit-transform: scaleX(1);
        -ms-transform: scaleX(1);
        transform: scaleX(1);
    }
    .featured-box-area .widget:hover .featured-box-item {
        box-shadow: 0px 0px 14px 0px #999;
        -o-box-shadow: 0px 0px 14px 0px #999;
        -moz-box-shadow: 0px 0px 14px 0px #999;
        -webkit-box-shadow: 0px 0px 14px 0px #999;
        transform: rotate(15deg);
        -o-transform: rotate(15deg);
        -webkit-transform: rotate(15deg);
        -moz-transform: rotate(15deg);
     }
@media only screen and (max-width:1000px) {

    .featured-box-area .widget {
        display: inline-block;
        margin: 2%!important;
		vertical-align:middle;
    }
    .featured-box-area{
        text-align: center;
    display: flex!important;
    overflow-x: scroll;
    }
}

	/* featured-box Area CSS Ends */

.PopularPosts .item-thumbnail-only {position: relative;z-index: 1;}
.PopularPosts .widget-content ul li:hover:before {color:$(maincolor);}

.PopularPosts .widget-content ul li:before{
	transition: 400ms;
    -o-transition: 400ms;
    -moz-transition: 400ms;
    -webkit-transition: 400ms;
}
.odd-f-box.container{
	opacity: 0;
    visibility: hidden;
    transition: opacity 1s ease;
    -webkit-transition: opacity 1s ease;
}
body.listposts .post-image {display: inline-block;vertical-align: middle;width: 37%;margin-right: 3%;}
body.listposts .embedd {display: inline-block;vertical-align: middle;width: 60%;}
body.listposts .cen, body.listposts .post-footer {text-align: left;}

body.listposts .post-image img{width: 100%;height: 300px;object-fit: cover;}
body.listposts .entry-title{font-size:26px;margin-top: 10px;}
body.listposts .meta-wrap{display:block;text-align: left;}





body.listposts .labelhome a{padding-left:0;margin:0;}
body.listposts .post-footer{margin-top:15px;}

body.slider3 .odd-f-box .item-title{
	line-height: 32px;
    font-size: 24px;
}
div#footer-top {
    padding-top: 60px;
    padding-bottom: 60px;
	border-top: 1px solid #ededed;
}


#footer-top #FooterNewsletter h3.title {text-align: center;font-weight: 600;text-transform:capitalize;    z-index: 9999;}
#footer-top #FooterNewsletter .PopularPosts .item-snippet {display: none;}

#footer-top #FooterNewsletter .PopularPosts article.post {display: inline-block;
    vertical-align: top;
    width: 23.25%;
    margin-right: 2%!important;
    margin-bottom: 5%;
    text-align: center;
    box-shadow: 0px 15px 30px 0px #ddd;
    -webkit-box-shadow: 0px 15px 30px 0px #ddd;
    -moz-box-shadow: 0px 15px 30px 0px #ddd;
    -o-box-shadow: 0px 15px 30px 0px #ddd;padding:0;}

#footer-top #FooterNewsletter .PopularPosts article.post:nth-child(4n+4) {margin-right: 0!important;}
#footer-top #FooterNewsletter .PopularPosts .item-thumbnail {float: none;width: 100%;display: block;overflow: hidden;}

#footer-top #FooterNewsletter .PopularPosts article.post img {width: 100%;border-radius: 0;height: auto;float: none;}
#footer-top #FooterNewsletter .PopularPosts .item-title {padding: 25px 10px;background: #fff;margin: 0;line-height: 24px;
    font-weight: 400;}
#footer-top #FooterNewsletter .widget-content.popular-posts article.post:before{display:none;}
#footer-top #FooterNewsletter .post-content {
    display: flex;
    flex-direction: column-reverse;
}
#footer-top #FooterNewsletter h3.post-title{
	font-size: 15px;
    text-transform: capitalize;
    padding: 15px 8px;
}
#footer-top #FooterNewsletter .post-snippet {
    display: none;
}


.footerbottom .PopularPosts .post-content {
    display: flex;
    flex-direction: row-reverse;
    justify-content: flex-end;
}


.footerbottom  .PopularPosts {
    counter-reset: section;
}

.footerbottom  .PopularPosts article.post:before {
    counter-increment: section;
    content: ""counter(section)"";
    position: absolute;
    top: 10px;
    right: 10px;
	font: $(second.font);
    line-height: 55px;
    text-align: center;
    z-index: 9;
    font-size: 100px;
    font-weight: 700;
    font-style: italic;
    color: #252525;
    z-index: 0;   
}
.footerbottom .PopularPosts article.post{background:none;    margin-bottom: 10px;}
.footerbottom .PopularPosts h3.post-title{
	font-size: 15px;
    text-transform: capitalize;
    padding: 15px 8px;
	width:70%;
}
.footerbottom .PopularPosts .item-thumbnail img {width: 72px;border-radius: 50%;-o-border-radius: 50%;-moz-border-radius: 50%;-webkit-border-radius: 50%;height: 72px;padding:0;object-fit:cover;}
.footerbottom .PopularPosts article.post:hover:before {color: $(maincolor);}

.footerbottom .PopularPosts article.post:before {transition: 400ms;-o-transition: 400ms;-webkit-transition: 400ms;-moz-transition: 400ms;}





#sidebar-wrapper .PopularPosts .post-content {
