    flex-direction: row-reverse;
    justify-content: flex-end;
}


#sidebar-wrapper  .PopularPosts {
    counter-reset: section;
}

#sidebar-wrapper .PopularPosts article.post:before {
    counter-increment: section;
    content: ""counter(section)"";
