	font-weight:700;
    letter-spacing: 1px;
    display: block;
    text-transform: uppercase;
	text-align:center;
	background:$(backcolor);
	color:$(secondcolor);
}
#footer h3.title,#footer h2.title,#footer h3,#footer h2 {color:#fff;}

.sidebar .widget h2.title:after, #related-posts h2.title:after, #footer h2.title:after, .sidebar .widget h3.title:after, #related-posts h3:after, #footer h3.title:after{position: absolute;left: 50%;bottom: -5px;-webkit-transform: translateX(-50%);-ms-transform: translateX(-50%);transform: translateX(-50%);display: block;width: 0;height: 0;border-left: 6px solid transparent;border-right: 6px solid transparent;border-top: 6px solid $(backcolor);content: "";}

.footerbottom .PopularPosts .post-snippet {
    display: none;
}
#sidebar-wrapper .PopularPosts .post-snippet {
    display: none;
}
#sidebar-wrapper .PopularPosts{overflow: auto;}


/* GRID Css Starts */
body.slider1 .odd-f-box {
    display: grid;
    grid-template-columns: 50% 25% 25%;
    grid-template-rows: 50% 50%;
    height: 75vh;
}

body.slider1 .odd-f-box .item:first-child {
    grid-column: 1 / 2;
    grid-row: 1 / span 2;
}

body.slider1 .odd-f-box .item:nth-child(2) {
    grid-column: 2 / span 3;
    grid-row: 1 / 2;
}

body.slider1 .odd-f-box .item:nth-child(3) {
    grid-column: 2 / 3;
}

body.slider1 .odd-f-box .item:nth-child(3),body.slider1 .odd-f-box .item:nth-child(4) {
    grid-row: 2 / 3;
}

body.slider1 .odd-f-box .item:nth-child(4) {
    grid-column: 3 / 4;
}


body.slider1 .odd-f-box .item:first-child .odd-image {
    height: 75vh;
	object-fit: cover;
	width:100%;
}

body.slider1 .odd-f-box .item:nth-child(2) .odd-image {
	height: 38vh;
	object-fit: cover;
	width:100%;
}

body.slider1 .odd-f-box .item:nth-child(3) .odd-image, body.slider1 .odd-f-box .item:nth-child(4) .odd-image {
	height: 38vh;
	object-fit: cover;
	width:100%;
}
body.slider1 .odd-f-box.container {
    width: initial;
}
body.slider1 .odd-f-box .item-title {
    line-height: 28px;
    font-size: 20px;
}

body.slider1 .odd-f-box .item:first-child .item-title {
    font-size: 26px;
    line-height: 40px;
}
/* GRID Css Ends */
