div#mc_embed_signup i {
    position: absolute;
    right: 0;
    font-size: 70px;
    -webkit-transform: translate(-25%, -150%) rotate(15deg);
    -ms-transform: translate(-25%, -150%) rotate(15deg);
    transform: translate(-25%, -150%) rotate(15deg);
    color: #9d9d9d;
    z-index: 0;
    opacity: 0.3;
}
#mc_embed_signup input#mc-embedded-subscribe {
    width: 100%;
    padding: 12px 0;
    color: $(secondcolor);
    cursor: pointer;
	background:$(backcolor);
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 12px;
	border:0;
}
#mc_embed_signup input#mce-EMAIL {
    width: 100%;
    border-radius: 0;
    box-sizing: border-box;
    height: 40px;
    padding-left: 15px;
}
.mctitle {
    font-size: 20px;
    text-align: center;
    font-weight: 600;
}

div#mc_embed_signup {
    padding: 40px 30px 10px;
    border-top: 5px solid $(backcolor);
    box-shadow: 0 5px 20px -6px rgba(0, 0, 0, 0.05), 0 0 1px rgba(0, 0, 0, 0.05);
    text-align: center;
    transition: box-shadow 0.4s;
}
div#mc_embed_signup:hover{
	box-shadow: 0 15px 30px -6px rgba(0, 0, 0, 0.1), 0 0 1px rgba(0, 0, 0, 0.05);
}

.item .item-image a:before {
    content: "";
    width: 100%;
    height: 100%;
    background: #000000;
    display: block;
    position: absolute;
    left: 0;
    top: 0;
    right: 0;
    opacity: .1;
    bottom: 0;
    z-index: 9;
}
.cat-title a:after {
    position: absolute;
    bottom: 0;
    top: 0;
    left: 0;
    padding: 0px;
    display: block;
    width: 100%;
    background: $(maincolor);
    content: "";
    transition: transform .4s ease;
    -webkit-transform: scaleX(0);
    -ms-transform: scaleX(0);
    transform: scaleX(0);
    z-index: -1;
}

.item:hover .cat-title a:after{
    -webkit-transform: scaleX(1);
    -ms-transform: scaleX(1);
    transform: scaleX(1);
}
.item:hover .cat-title a{
    color:#fff;
}
#footer-top div#mc_embed_signup {border-top: 0;max-width: 600px;box-shadow: none;margin: 0 auto;padding-top: 0;}

#footer-top div#mc_embed_signup i {
